import {weeks} from './content';
import type {LessonGuide} from './lesson-types';
type Reading=LessonGuide['resourceSections'][number];
interface Topic {intro:[string,string];reading:Reading[];study:string[];build:string[];input:string;output:string;question:string;answer:string;pitfall:string;code?:string;explanation?:string}
const read=(title:string,url:string,focus:string,content:string,action:string):Reading=>({title,url,focus,read:content,action});
const tour='https://go.dev/tour/';
const gin='https://go.dev/doc/tutorial/web-service-gin';
const pg='https://www.postgresql.org/docs/current/tutorial.html';
const docker='https://docs.docker.com/get-started/';
const react='https://react.dev/learn';
const testing='https://go.dev/doc/tutorial/add-a-test';
const topics:Topic[]=[
 {intro:['متغیر یک نام برای مقدار با نوع مشخص است. در Go نوع int برای عدد صحیح، float64 برای عدد اعشاری و string برای متن به کار می‌رود. شرط if مسیر اجرای برنامه را انتخاب می‌کند؛ حلقه for یک بخش را تا زمانی که شرط برقرار است تکرار می‌کند. پیش از اجرای کد، مقدار متغیرها را روی کاغذ دنبال کن تا اجرای برنامه قابل پیش‌بینی شود.','برای شروع به سرویس یا دیتابیس نیاز نداری. در یک پوشه فایل main.go بساز؛ package main و تابع main نقطه شروع برنامه‌اند. دستور go run main.go فایل را کامپایل و اجرا می‌کند. خروجی درست کافی نیست: تغییر شرط حلقه، ترتیب شرط‌های FizzBuzz و ورودی نامعتبر باید رفتاری قابل توضیح داشته باشند.'],reading:[read('A Tour of Go','https://go.dev/tour/basics/1','Basics و Flow control: Variables، Basic types، For، If','در Basics نحوه تعریف متغیر و تفاوت := با var را بخوان؛ سپس در Flow control مثال For و If را اجرا کن. این نوبت سراغ Interface و Concurrency نرو.','مثال جمع عددهای ۱ تا ۵ را تغییر بده؛ قبل از Run نتیجه ۱۵ را پیش‌بینی و بعد بررسی کن.'),read('Go by Example','https://gobyexample.com/','Variables، For، If/Else و Switch','فقط مثال‌های هم‌نام را از فهرست صفحه باز کن. برای هر مثال متغیر ورودی و شرط خروج را پیدا کن.','یک نسخه از هر مثال بدون نگاه بنویس و یک ورودی دیگر به آن بده.')],study:['Go را از go.dev نصب کن؛ در Terminal دستور go version را اجرا و نسخه را یادداشت کن. پوشه week01 و فایل main.go بساز.','کد زیر را اجرا کن و برای i=1 تا i=5 مقدار i و total را در جدول بنویس. سپس شرط <= را با < عوض کن و نتیجه ۱۰ را توضیح بده.','یک متغیر score با مقدار ۱۸ بساز؛ با if برای score>=10 پیام pass و در غیر این صورت retry چاپ کن. مقدار را ۹ کن و خروجی را پیش‌بینی کن.'],build:['سه برنامه جدا برای ماشین‌حساب، زوج/فرد و FizzBuzz بساز؛ ورودی را با fmt.Scan بخوان و خطای خواندن را بررسی کن.','در ماشین‌حساب پیش از تقسیم، صفر بودن مقسوم‌علیه را بررسی کن. برای عملگر نامعتبر پیام مشخص بده.','در FizzBuzz ابتدا بخش‌پذیری هم‌زمان بر ۳ و ۵، سپس بر ۳ و سپس بر ۵ را بررسی کن. خروجی اعداد ۱ تا ۱۰۰ را با پنج نمونه مرزی تطبیق بده.'],input:'جمع ۱..۵؛ score=9؛ FizzBuzz برای 1،3،5،15،16؛ ماشین‌حساب 8 / 0',output:'جمع = 15؛ score پیام retry؛ خروجی FizzBuzz به‌ترتیب 1،Fizz،Buzz،FizzBuzz،16؛ تقسیم بر صفر پیام خطا دارد و برنامه panic نمی‌کند.',question:'چرا حلقه مجموع با <=5 مقدار ۱۵ و با <5 مقدار ۱۰ می‌دهد؟ قبل از اجرا دو خروجی را بنویس.',answer:'با <= آخرین تکرار i=5 است و ۱+۲+۳+۴+۵=۱۵؛ با < آخرین تکرار i=4 و مجموع ۱۰ است. در i=6 یا i=5 شرط متناظر نادرست می‌شود.',pitfall:'اگر در FizzBuzz شرط مضرب ۳ را پیش از مضرب ۱۵ بنویسی، عدد ۱۵ فقط Fizz می‌شود. ترتیب شرط‌ها بخشی از منطق برنامه است.',code:'package main\n\nimport "fmt"\n\nfunc main() {\n    total := 0\n    for i := 1; i <= 5; i++ {\n        total += i\n    }\n    fmt.Println(total) // 15\n}',explanation:'total بیرون حلقه تعریف شده تا جمع را حفظ کند. i++ بعد از بدنه اجرا می‌شود و حلقه وقتی i=6 باشد متوقف می‌شود.'},
 {intro:['تابع ورودی می‌گیرد و نتیجه برمی‌گرداند؛ جداکردن محاسبه از چاپ باعث می‌شود همان منطق را بعداً در CLI و API استفاده کنی. Array طول ثابت و بخشی از نوع دارد، اما Slice نمایی با طول و ظرفیت روی آرایه زیرین است. append می‌تواند آرایه زیرین را عوض کند، بنابراین نتیجه‌اش را باید دوباره به Slice نسبت بدهی.','Struct چند ویژگی مرتبط را در یک مقدار جمع می‌کند؛ Task می‌تواند ID، Title و Done داشته باشد. Map برای پیدا کردن مقدار با کلید مفید است و ترتیب پیمایشش تضمین‌شده نیست. در این درس یک منبع حقیقت برای فهرست Task انتخاب می‌کنی و داده خالی و شناسه تکراری را صریح مدیریت می‌کنی.'],reading:[read('A Tour of Go','https://go.dev/tour/moretypes/1','More types: Structs، Arrays، Slices و Maps','بخش More types را از Structs تا Maps بخوان؛ به zero value، len، cap و append توجه کن.','یک [3]int و یک []int تعریف کن و نتیجه append و len را کنار هم چاپ کن.')],study:['نوع Task را با ID int، Title string و Done bool تعریف کن؛ پنج نمونه با شناسه یکتا بساز.','تابع countDone(tasks []Task) int بنویس که فقط بشمارد و چاپ نکند؛ روی Slice خالی صفر برگرداند.','یک Map از ID به Task بساز. دو مقدار برگشتی lookup را بررسی کن تا نبود کلید با Task خالی اشتباه نشود.'],build:['توابع add، list و filterDone را روی []Task بساز. افزودن باید نتیجه جدید Slice را به فراخواننده برگرداند.','پیش از add تمام IDها را برای تکراری‌بودن بررسی کن؛ تابع مسئول چاپ پیام نباشد و خطا یا نتیجه را برگرداند.','فهرست پنج Task شامل دو Done=true بساز؛ فیلتر، شمارش و فهرست خالی را با انتظار نوشته‌شده اجرا کن.'],input:'Taskهای 1 و 3 انجام‌شده؛ سه Task دیگر باز؛ سپس فهرست خالی و add با ID=3',output:'countDone برابر 2؛ فیلتر فقط IDهای 1 و 3؛ فهرست خالی خروجی خالی؛ شناسه تکراری به فهرست اضافه نمی‌شود.',question:'تفاوت len و cap در Slice چیست و چرا نتیجه append را باید نگه داشت؟',answer:'len تعداد عناصر قابل دسترسی فعلی و cap ظرفیت از ابتدای Slice تا انتهای آرایه زیرین است. append ممکن است آرایه تازه بسازد و Slice جدید برگرداند.',pitfall:'قرار دادن ID از len(tasks)+1 بعد از حذف می‌تواند شناسه تکراری تولید کند؛ شمارنده مستقل یا روش تولید ID مشخص داشته باش.',code:'type Task struct {\n    ID int\n    Title string\n    Done bool\n}\n\nfunc countDone(tasks []Task) int {\n    count := 0\n    for _, task := range tasks {\n        if task.Done { count++ }\n    }\n    return count\n}',explanation:'ورودی تابع Slice است؛ شمارش روی داده خوانده می‌شود و داده ورودی تغییر نمی‌کند.'},
 {intro:['Go آرگومان‌ها را به‌صورت مقدار منتقل می‌کند. Pointer آدرس مقدار را نگه می‌دارد؛ با dereference می‌توان مقدار اصلی را تغییر داد. Method تابعی با گیرنده است و گیرنده Pointer وقتی مفید است که رفتار باید وضعیت اصلی را عوض کند یا از کپی بزرگ جلوگیری کند.','Interface قرارداد رفتار است، نه فهرست فیلدها؛ یک نوع وقتی Methodهای لازم را داشته باشد به‌طور ضمنی آن را پیاده می‌کند. error برای شکست قابل انتظار مثل نبود Task است. به‌جای panic در ورودی معمول کاربر، خطا را به لایه بالاتر برگردان تا آن لایه تصمیم بگیرد پیام CLI یا پاسخ HTTP چیست.'],reading:[read('A Tour of Go','https://go.dev/tour/methods/1','Pointers در More types؛ Methods و Interfaces','مثال Pointer و سپس Method با pointer receiver و Interface را بخوان؛ مثال error را در بخش Methods and interfaces پیدا کن.','یک تابع را یک بار با Task و یک بار با *Task بنویس؛ تفاوت Done بعد از فراخوانی را نشان بده.')],study:['روی Task متد MarkDone با گیرنده *Task بنویس و مقدار قبل و بعد از فراخوانی را چاپ کن.','Interface کوچک Store با Get(id int) (Task,error) تعریف کن؛ نوع MemoryStore را با همان Method قابل استفاده کن.','برای ID ناموجود خطای مشخص برگردان؛ در main آن را بررسی و بدون panic پیام بده.'],build:['update و delete را به MemoryStore اضافه کن؛ نبود شناسه باید خطا برگرداند و بقیه Taskها را تغییر ندهد.','تعویض Store با نوع دیگری را با یک تابع مصرف‌کننده Interface امتحان کن؛ تابع مصرف‌کننده نام MemoryStore را نداند.','یک سناریوی ایجاد، تغییر، حذف و حذف دوباره را اجرا و خطاهای هر مرحله را در README بنویس.'],input:'Task با ID=7 و Done=false؛ MarkDone؛ سپس delete(7) و delete(7) دوباره',output:'پس از Method مقدار اصلی Done=true؛ حذف اول موفق؛ حذف دوم error قابل توضیح و بدون panic؛ IDهای دیگر حفظ می‌شوند.',question:'چرا تغییر فیلد روی پارامتر Task داخل تابع الزاماً Task اصلی را تغییر نمی‌دهد؟',answer:'پارامتر معمولی کپی مقدار است؛ تغییر کپی به فراخواننده منتقل نمی‌شود. با *Task آدرس همان مقدار در اختیار تابع است و تغییر از طریق آن روی مقدار اصلی اثر می‌گذارد.',pitfall:'Interface بزرگ برای همه عملیات از ابتدا نساز؛ مصرف‌کننده فقط قرارداد کوچکی را بخواهد که واقعاً استفاده می‌کند.',code:'func (t *Task) MarkDone() {\n    t.Done = true\n}\n\ntask := Task{ID: 7}\ntask.MarkDone() // task.Done == true',explanation:'قطعه کد به نوع Task درس قبل نیاز دارد. گیرنده Pointer موجب تغییر خود task می‌شود.'},
 {intro:['Module واحد نسخه‌بندی و وابستگی Go است و با go.mod معرفی می‌شود. Package گروه فایل‌های Go با نام پکیج مشترک در یک پوشه است. جداکردن package ذخیره‌سازی از main اجازه می‌دهد رفتار JSON را بدون اجرای CLI تست کنی.','JSON قالب تبادل داده است؛ struct tagها نام فیلدهای خروجی را مشخص می‌کنند. خواندن فایل، decode و اعتبارسنجی سه مرحله جدا هستند. نبود فایل می‌تواند به معنی شروع با فهرست خالی باشد، اما JSON خراب نباید بی‌صدا با فایل خالی جایگزین شود. تست باید این رفتارهای متفاوت را ثابت کند.'],reading:[read('Go Tutorials','https://go.dev/doc/tutorial/create-module','Create a module و Add a test','ماژول تازه را با go mod init بساز؛ سپس آموزش Add a test را از فهرست دنبال کن و قالب TestXxx را ببین.','منطق Store را به package جدا منتقل کن و با go test ./... آن را اجرا کن.'),read('encoding/json','https://pkg.go.dev/encoding/json','Marshal، Unmarshal و struct tags','امضا و مثال‌های Marshal/Unmarshal را بخوان و بررسی کن چه زمانی error برمی‌گردد.','Task را با json:"title" ذخیره کن، از فایل بخوان و همان مقدار را مقایسه کن.')],study:['در پوشه پروژه go mod init example.com/taskcli را اجرا کن؛ main و package ذخیره‌سازی را جدا کن.','یک Task را با json.Marshal به []byte تبدیل کن؛ خروجی و خطا را بررسی کن و با os.WriteFile در مسیر تمرینی بنویس.','با os.ReadFile و json.Unmarshal برگردان؛ برای فایل ناموجود، JSON خراب و آرایه خالی سه تست بنویس.'],build:['دستورهای add، list، done و delete را به Store فایل JSON وصل کن؛ پس از هر تغییر موفق فایل را ذخیره کن.','پیش از overwrite، decode فایل قبلی را انجام بده؛ خطای فایل خراب را گزارش کن و فایل خراب را نگه دار.','CLI را ببند، دوباره اجرا کن و Task قبلی را بخوان؛ داده نمونه و تست‌ها را commit کن و فایل واقعی شخصی را وارد مخزن نکن.'],input:'فایل شامل [{"id":1,"title":"Go","done":false}]؛ add یک Task؛ بستن و اجرای دوباره؛ سپس فایل {bad',output:'پس از اجرای دوباره هر دو Task موجودند؛ go test ./... موفق؛ فایل خراب پیام خطای decode دارد و بی‌صدا پاک نمی‌شود.',question:'Module و Package چه تفاوتی دارند و چرا تست فایل خراب لازم است؟',answer:'Module با go.mod وابستگی و نسخه را تعریف می‌کند و می‌تواند چند Package داشته باشد. Package مرز کد در پوشه است. تست فایل خراب ثابت می‌کند شکست decode موجب ازبین‌رفتن داده قبلی نمی‌شود.',pitfall:'نادیده‌گرفتن error از ReadFile یا Unmarshal می‌تواند داده خالی جعلی بسازد و در ذخیره بعدی فایل واقعی را خراب کند.'},
 {intro:['HTTP یک قرارداد درخواست و پاسخ است: client متد، مسیر، header و گاهی body می‌فرستد؛ server با status، header و body پاسخ می‌دهد. JSON فقط قالب body است و به‌تنهایی نشان‌دهنده موفقیت درخواست نیست. 200 یعنی پاسخ موفق طبق قرارداد؛ 404 یعنی منبع یا مسیر مورد نظر پیدا نشده است.','Backend محل اجرای قواعد و دسترسی داده است. مرورگر یا Postman نمی‌تواند مالکیت یا صحت داده را تضمین کند؛ سرور باید درخواست را بررسی کند. در این مرحله هدف مشاهده مسیر درخواست است، نه افزودن هویت یا دیتابیس. endpoint سلامت را از پاسخ فهرست Task جدا کن تا هرکدام قرارداد روشن داشته باشند.'],reading:[read('Go RESTful API Tutorial',gin,'Create the data؛ Write a handler to return all items؛ Run the code','مدل داده، handler فهرست و راه اجرای curl را بخوان؛ به مسیر، status و JSON در پاسخ دقت کن.','endpoint نمونه را اجرا کن و با curl -i هم header و هم body را ببین؛ داده album را به Task تطبیق بده.')],study:['یک درخواست GET را روی کاغذ به method، path، headers و body تقسیم کن؛ برای پاسخ status و content-type را بنویس.','آموزش Gin را اجرا کن و با curl -i پاسخ فهرست را ببین؛ ثبت کن کدام خط header است و کجا body شروع می‌شود.','handler سلامت را طوری تعریف کن که JSON با status مشخص بدهد؛ مسیر ناشناخته را جدا آزمایش کن.'],build:['GET /health را با پاسخ {"status":"ok"} و GET /tasks را با آرایه Task در حافظه بساز.','در Bruno یا Postman سه درخواست برای /health، /tasks و /missing ذخیره کن؛ status و body واقعی هرکدام را یادداشت کن.','سرور را متوقف کن و همان درخواست را بفرست؛ تفاوت خطای اتصال با پاسخ HTTP 404 را در گزارش توضیح بده.'],input:'GET /health؛ GET /tasks روی فهرست خالی؛ GET /missing؛ درخواست پس از توقف سرور',output:'health پاسخ 200 و JSON؛ tasks آرایه خالی؛ missing پاسخ 404؛ سرور متوقف خطای اتصال دارد و هیچ status HTTP از سرور دریافت نمی‌شود.',question:'آیا وجود JSON با فیلد error برای تشخیص شکست کافی است؟',answer:'قرارداد باید status و body را با هم تعریف کند؛ client ابتدا status را بررسی می‌کند و سپس body را طبق نوع پاسخ می‌خواند. پیام JSON خطا با 200 رفتار مبهم ایجاد می‌کند.',pitfall:'موفق‌شدن درخواست در Postman نشانه امن‌بودن API نیست؛ هنوز هویت، مجوز و اعتبارسنجی اضافه نشده‌اند.'},
 {intro:['REST منابع را با نام مشخص مثل tasks معرفی می‌کند و از متد HTTP برای نوع عملیات استفاده می‌کند. GET فهرست یا یک Task را می‌خواند؛ POST یک Task می‌سازد. شناسه در مسیر، داده JSON در body و پارامترهای query سه کانال متفاوت‌اند که باید جدا اعتبارسنجی شوند.','Gin مسیریابی و تبدیل JSON به Struct را ساده می‌کند؛ قواعد مسئله را به‌جای تو نمی‌نویسد. decode موفق JSON به معنی عنوان معتبر نیست. خطای نحوی JSON، عنوان خالی و نبود شناسه سه حالت جدا با پاسخ قابل پیش‌بینی‌اند.'],reading:[read('Go RESTful API Tutorial',gin,'Add code to handle POST requests؛ Write a handler to return a specific item','handlerهای POST و پارامتر مسیر را کنار handler فهرست بخوان. BindJSON و وضعیت پاسخ‌ها را دنبال کن.','برای هر handler نمونه ورودی معتبر و نامعتبر تعریف کن و پیش از اجرای آن status مورد انتظار را بنویس.')],study:['جدول قرارداد برای GET /tasks، POST /tasks و GET /tasks/:id بنویس؛ body، status و نمونه خطا را کنار هر مسیر قرار بده.','مدل ورودی CreateTask را از مدل داده ذخیره‌شده جدا کن؛ ID را server تولید کند.','مسیر شناسه‌دار را اجرا و تفاوت پارامتر نامعتبر با شناسه معتبر ولی ناموجود را مشخص کن.'],build:['سه handler را روی MemoryStore پیاده کن و منطق ساخت Task را از handler به تابع کوچک منتقل کن.','عنوان را TrimSpace کن و عنوان خالی را رد کن؛ JSON خراب را پیش از استفاده از مدل ورودی گزارش کن.','POST معتبر بفرست، ID پاسخ را بردار و با GET همان ID برگردان؛ سپس شناسه ناشناخته و JSON خراب را امتحان کن.'],input:'POST /tasks با {"title":"learn Go"}؛ سپس {"title":"   "}؛ سپس GET /tasks/999',output:'ساخت معتبر 201 و ID تولیدشده؛ عنوان سفید پاسخ 4xx و بدون ساخت Task؛ شناسه ناموجود 404. GET چیزی به داده اضافه نمی‌کند.',question:'چرا decode موفق body هنوز نیاز به validation دارد؟',answer:'decode فقط قالب و نوع قابل تبدیل را بررسی می‌کند؛ رشته خالی همچنان string معتبر است ولی ممکن است قواعد مسئله آن را نپذیرد.',pitfall:'از GET برای حذف یا تغییر وضعیت استفاده نکن؛ client و cache ممکن است GET را بدون انتظار تغییر داده دوباره اجرا کنند.'},
 {intro:['دیتابیس رابطه‌ای داده را در جدول‌هایی با کلید و محدودیت ذخیره می‌کند. Primary Key هویت رکورد و Foreign Key ارتباط معتبر را مشخص می‌کند. JOIN رکوردهای مرتبط را کنار هم می‌آورد؛ Transaction چند تغییر را به یک واحد commit یا rollback تبدیل می‌کند.','در Go باید متن SQL و مقدار ورودی را جدا به driver بدهی. پارامتر $1 در PostgreSQL مقدار است، نه بخشی از متن SQL؛ چسباندن ورودی کاربر به query مرز داده و دستور را خراب می‌کند. اتصال دیتابیس، اجرای query و پیمایش rows هرکدام می‌توانند خطا بدهند و باید مدیریت شوند.'],reading:[read('PostgreSQL Tutorial',pg,'SQL Language: Creating a New Table، Querying a Table، Joins؛ Advanced Features: Transactions','ابتدا جدول و SELECT را بخوان؛ بعد JOIN و Transaction را با جدول نمونه اجرا کن.','جدول users و tasks را با کلید مالک بساز و یک JOIN و rollback را روی داده ساختگی نشان بده.'),read('Go database access','https://go.dev/doc/database/querying','Querying for data و parameterized queries','روش QueryRow و Query و مدیریت rows را بخوان؛ placeholder با driver دیتابیس هماهنگ است.','تابع GetTask(ownerID,taskID) را با query پارامتری بنویس.')],study:['schema users(id,email) و tasks(id,user_id,title,done) را با Foreign Key رسم کن؛ برای email یک قید یکتا در نظر بگیر.','در DBeaver یا psql دو کاربر و سه Task درج کن؛ JOIN بزن و مالک هر Task را نشان بده.','BEGIN را اجرا، یک تغییر اعمال و ROLLBACK کن؛ ثابت کن مقدار قبلی برگشته است.'],build:['دستور ساخت schema را در migration قابل تکرار ثبت کن و DATABASE_URL را از محیط بخوان؛ connection string واقعی را commit نکن.','MemoryStore را با PostgreSQLStore جایگزین کن؛ QueryRow، Query، Scan و Close کردن rows را مدیریت کن.','سرویس را restart کن و Taskها را دوباره بخوان؛ ورودی شبیه SQL را به‌عنوان عنوان ذخیره کن و ثابت کن دستور اجرا نشده است.'],input:'user A با id=1 و دو Task؛ user B با id=2 و یک Task؛ Transaction تغییر done سپس rollback',output:'JOIN دقیقاً سه رکورد با مالک درست می‌دهد؛ rollback مقدار done را برمی‌گرداند؛ restart سرویس داده را حذف نمی‌کند.',question:'چرا "WHERE id="+input با WHERE id=$1 یکسان نیست؟',answer:'در حالت اول ورودی بخشی از دستور SQL می‌شود؛ در حالت پارامتری driver آن را جداگانه به‌عنوان مقدار ارسال می‌کند و ساختار query ثابت می‌ماند.',pitfall:'نوشتن query پارامتری به‌تنهایی مالکیت Task را تضمین نمی‌کند؛ شرط user_id هم باید در خواندن و تغییر رکورد باشد.'},
 {intro:['Authentication می‌پرسد درخواست متعلق به چه کسی است؛ Authorization می‌پرسد همین فرد اجازه انجام این عمل روی این رکورد را دارد یا نه. JWT امضاشده می‌تواند هویت و زمان انقضا را حمل کند، اما داشتن token معتبر به معنی مالک همه Taskها بودن نیست.','رمز عبور با تابع مخصوص password hashing و salt ذخیره می‌شود؛ رمزگذاری برگشت‌پذیر یا hash سریع مثل SHA-256 جایگزین مناسبی برای ذخیره رمز نیست. token را باید با الگوریتم مورد انتظار، امضای معتبر، زمان انقضا و claimهای لازم بررسی کنی؛ محتویات JWT معمولاً محرمانه نیستند.'],reading:[read('OWASP Authentication Cheat Sheet','https://cheatsheetseries.owasp.org/cheatsheets/Authentication_Cheat_Sheet.html','Password storage و Authentication responses','تفاوت سیاست رمز، ذخیره امن و پیام خطای ورود را بخوان؛ از راهنمای password storage مرتبط با نسخه انتخابی پیروی کن.','ثبت‌نام را طوری بساز که در DB و log هیچ رمز خامی باقی نماند.'),read('OWASP Authorization Cheat Sheet','https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html','Deny by default و Validate permissions on every request','کنترل مجوز در هر درخواست و بررسی رابطه کاربر با منبع را بخوان.','برای GET، PATCH و DELETE Task کاربر دیگر تست جدا بنویس.')],study:['جدول کاربر، هش رمز و داده لازم token را روی کاغذ مشخص کن؛ هیچ رمز یا secret واقعی در مثال‌ها نگذار.','جریان ثبت‌نام، ورود، اعتبارسنجی token و دریافت user_id را رسم کن؛ نقطه کنترل مالکیت را جدا علامت بزن.','جدول مجوز A و B برای Task متعلق به A بنویس؛ بدون token و token منقضی را هم در جدول بگذار.'],build:['ثبت‌نام و ورود را با کتابخانه معتبر password hash و JWT انتخابی پیاده کن؛ الگوریتم و زمان انقضا را صریح پیکربندی کن.','user_id را از هویت تأییدشده بگیر؛ در queryهای SELECT، UPDATE و DELETE شرط مالکیت را همراه ID قرار بده.','با دو حساب ساختگی A و B درخواست‌های خواندن، تغییر و حذف Task A را با token B بفرست و قبل/بعد DB را مقایسه کن.'],input:'Task id=41 متعلق به A؛ token معتبر B؛ درخواست GET/PATCH/DELETE روی /tasks/41؛ سپس token منقضی A',output:'B هیچ داده خصوصی نمی‌گیرد و هیچ تغییری رخ نمی‌دهد؛ قرارداد پاسخ 403 یا 404 به‌صورت یکدست اجرا می‌شود. token منقضی 401 می‌گیرد.',question:'چرا JWT معتبر کاربر B برای خواندن Task A کافی نیست؟',answer:'اعتبار JWT فقط هویت B را تأیید می‌کند. سرور جداگانه باید ارتباط B با Task A و مجوز عمل را بررسی کند؛ در این پروژه B مالک نیست.',pitfall:'user_id ارسالی در body را به‌عنوان مالک قابل اعتماد قبول نکن. رمز خام، secret امضا و token کامل را در log ننویس.'},
 {intro:['Middleware رفتاری است که پیرامون handler اجرا می‌شود؛ برای ثبت مدت درخواست، بازیابی panic یا بررسی هویت مناسب است. Validation ورودی را پیش از اجرای قواعد تجاری بررسی می‌کند. Handler ورودی و خروجی HTTP را مدیریت می‌کند؛ service قواعد و repository دسترسی داده را بر عهده می‌گیرد.','این جداسازی برای فهم و تست است و نیاز به ده‌ها interface و پوشه ندارد. قرارداد خطا باید واضح باشد: JSON خراب با خطای دیتابیس یکسان نیست و پیام داخلی DB نباید به کاربر نشت کند. مسیر دسترسی داده پس از جابه‌جایی کد همچنان باید کنترل مالکیت داشته باشد.'],reading:[read('Gin Documentation','https://gin-gonic.com/en/docs/','Middleware و Model binding and validation','در مستندات، middleware و binding/validation را پیدا کن؛ تفاوت کنترل decode و قواعد فیلد را ببین.','چهار body خراب را به endpoint بده و status و قالب پاسخ را مقایسه کن.')],study:['یک درخواست create را از handler تا service و repository دنبال کن و مسئولیت هر تابع را در یک جمله بنویس.','قواعد title غیرخالی و محدودیت طول و status مجاز را تعریف کن؛ یک قالب JSON برای error با code و message بساز.','middleware زمان‌سنج با request ID بنویس؛ فقط method، path، status و مدت را log کن و اطلاعات حساس را حذف کن.'],build:['چهار درخواست title خالی، status ناشناخته، JSON ناقص و عنوان بیش‌ازحد طولانی را به مجموعه تست اضافه کن.','منطق مشترک خطا را در یک نقطه تبدیل به HTTP کن؛ برای خطای DB پاسخ عمومی 5xx و log داخلی بدون secret داشته باش.','پس از جداکردن لایه‌ها، تست مالکیت هفته ۸ را دوباره اجرا کن تا refactor مجوز را دور نزده باشد.'],input:'title=""؛ status="teleported"؛ body={bad؛ title طول 501 با سقف قراردادی 500',output:'هر چهار درخواست 4xx ساختاریافته و بدون تغییر DB دارند؛ خطای داخلی DB، stack trace یا query حساس را به client نمی‌دهد.',question:'Validation عنوان خالی باید پیش از write دیتابیس چه نتیجه‌ای داشته باشد؟',answer:'درخواست با خطای قابل فهم رد می‌شود و repository تغییری نمی‌نویسد؛ خطاهای نامعتبرکاربر 4xx هستند و با خرابی سرویس 5xx فرق دارند.',pitfall:'پوشه‌بندی به‌تنهایی معماری نیست؛ جابه‌جایی handler نباید کنترل مالکیت یا مدیریت error را حذف کند.'},
 {intro:['Unit Test رفتار یک واحد کوچک را با ورودی و خروجی مشخص می‌سنجد. Integration Test همکاری واقعی اجزا، مثلاً handler و PostgreSQL، را بررسی می‌کند. جایگزینی DB با map در تستی که ادعای تست دیتابیس دارد، خطاهای SQL، migration و Transaction را آشکار نمی‌کند.','هر تست باید داده خودش را بسازد و مستقل از ترتیب اجرا باشد. جدول ورودی و انتظار را پیش از کد بنویس. تست مجوز باید endpoint را با هویت کاربر دوم صدا بزند و ثابت کند هم پاسخ و هم داده ذخیره‌شده درست مانده‌اند؛ فقط صداشدن یک تابع authorization کافی نیست.'],reading:[read('Go Add a test',testing,'Test functions، failures و go test','قالب نام TestXxx و استفاده از testing.T را بخوان؛ تفاوت شکست تست و خروج موفق دستور را ببین.','یک تست را عمداً با انتظار نادرست اجرا کن؛ بعد منطق را اصلاح و پاس‌شدنش را مشاهده کن.'),read('net/http/httptest','https://pkg.go.dev/net/http/httptest','NewRecorder و NewRequest','روش ساخت request و ثبت پاسخ handler در حافظه را بخوان.','یک handler واقعی را با درخواست JSON سالم و خراب فراخوانی و status را assert کن.')],study:['برای تابع validation سه case بنویس: عنوان سالم، سفید و بلند؛ هر case یک انتظار روشن داشته باشد.','در DB مخصوص تست migration را اجرا کن؛ داده آزمایشی با شناسه یا transaction مستقل بساز و پایان تست پاک‌سازی کن.','یک تست مجوز را روی handler کامل بنویس و بررسی کن نبود مالکیت واقعاً جلوی خواندن DB را گرفته است.'],build:['سناریوی ثبت‌نام، ورود، ساخت، خواندن، تغییر وضعیت و حذف Task را با درخواست HTTP تست کن.','برای token B روی Task A خواندن/ویرایش/حذف را جدا امتحان کن و ثابت کن مقدار Task A عوض نشده است.','تست‌ها را با go test ./... و در صورت امکان go test -race ./... اجرا کن؛ DB آزمایشی را با DB شخصی یکی نکن.'],input:'A و B؛ Task A با title="private"؛ درخواست B برای تغییر title="stolen"؛ سپس GET با A',output:'درخواست B رد می‌شود و GET با A همچنان private را برمی‌گرداند؛ اجرای جدا یا چندباره تست به داده باقی‌مانده وابسته نیست.',question:'چه چیزی تست مجوز یکپارچه را از تست فقط تابع مجوز متفاوت می‌کند؟',answer:'تست یکپارچه درخواست واقعی را از routing، هویت و handler عبور می‌دهد و اثر نهایی روی پاسخ و DB را می‌سنجد؛ اتصال نادرست لایه‌ها هم آشکار می‌شود.',pitfall:'تست سبز بدون assertion روی نتیجه می‌تواند حتی وقتی API اشتباه کار می‌کند سبز بماند. تست‌کردن فقط status=200 کافی نیست.'},
 {intro:['Goroutine یک اجرای هم‌زمان سبک است. Concurrency سازمان‌دهی چند کار در بازه مشترک است و الزاماً به معنی اجرای هم‌زمان روی چند هسته نیست. Channel برای تبادل مقدار و هماهنگی مناسب است؛ ارسال روی channel بدون دریافت‌کننده ممکن است بلوکه شود و پایان برنامه باید طراحی شده باشد.','Worker pool تعداد اجراهای هم‌زمان را محدود می‌کند تا CPU، شبکه یا DB زیر بار نامحدود نروند. Redis می‌تواند نتیجه قابل بازسازی را با TTL cache کند؛ cache نباید تنها محل نگهداری داده اصلی باشد. پس از تغییر Task، cache مرتبط باید منقضی یا invalidate شود تا داده کهنه برنگردد.'],reading:[read('A Tour of Go','https://go.dev/tour/concurrency/1','Concurrency: Goroutines، Channels و Range and Close','مثال send/receive و بسته‌شدن channel را بخوان؛ مشخص کن چه کسی مالک بستن channel است.','پنج کار را بین سه worker پخش کن و برای پایان هرکدام منتظر بمان.'),read('Redis documentation','https://redis.io/docs/latest/','GET، SET و EXPIRE در مستندات فرمان‌ها','مدل key/value و TTL را بخوان؛ داده تمرینی را با زمان انقضا ثبت کن.','یک key را با TTL کوتاه بساز، قبل و بعد انقضا GET کن و زمان‌ها را ثبت کن.')],study:['یک Goroutine بساز که نتیجه محاسبه را روی channel بفرستد؛ در main دریافت کن تا قبل از نتیجه خارج نشوی.','برای پنج job، سه worker و یک جمع‌کننده نتیجه رسم کن؛ ارسال jobها و close شدن ورودی را فقط به producer بسپار.','تفاوت DB اصلی و cache را برای فهرست Task توضیح بده و سیاست TTL یا invalidate بنویس.'],build:['jobهای 1..5 را به سه worker بده؛ هر نتیجه ID همان job را داشته باشد و نتایج را پیش از خروج جمع کن.','خطای یک job را به‌صورت نتیجه error منتقل کن؛ پایان بقیه کارها و shutdown را طوری مدیریت کن که goroutine گیر نکند.','یک پاسخ فهرست قابل بازسازی را cache کن؛ expire را مشاهده کن و قطع Redis را طوری کنترل کن که DB هنوز قابل استفاده باشد.'],input:'jobهای [1,2,3,4,5]؛ سه worker؛ cache key آزمایشی با TTL=2 ثانیه',output:'پنج ID یکتا برمی‌گردد؛ ترتیب ممکن است فرق کند؛ برنامه پایان می‌یابد. key بعد از انقضا پیدا نمی‌شود و داده اصلی DB باقی است.',question:'چرا ترتیب خروجی workerها الزاماً ۱ تا ۵ نیست؟',answer:'زمان پایان goroutineها به زمان‌بندی وابسته است؛ درستی را با مجموعه IDها و نبود تکرار می‌سنجیم، مگر ترتیب صریحاً جزو قرارداد باشد.',pitfall:'sleep جای هماهنگی پایان goroutine نیست. بستن channel توسط چند worker می‌تواند panic ایجاد کند.'},
 {intro:['Image دستورالعمل‌ها و فایل‌های لازم برای ساخت محیط اجرای برنامه را نگه می‌دارد؛ Container یک نمونه در حال اجرای آن است. فایل داخل container موقتی است مگر در volume یا محل پایدار نگهداری شود. Compose چند سرویس مثل API و DB را با شبکه و تنظیمات مشترک توصیف می‌کند.','متغیر محیطی تنظیمات را از کد جدا می‌کند، اما به‌خودی‌خود secret را امن نمی‌کند؛ فایل env واقعی و log نباید منتشر شوند. در شبکه Compose نام سرویس DB جای localhost را می‌گیرد. healthcheck و retry آماده‌شدن DB را از صرفاً شروع‌شدن process جدا می‌کنند.'],reading:[read('Docker Get Started',docker,'Images، Containers، Dockerfile و Docker Compose','مفهوم image/container را بخوان و مثال چندسرویسی Compose را دنبال کن؛ بخش volume را برای داده پایدار ببین.','Go API و PostgreSQL را با دو سرویس، شبکه داخلی و volume مجزای DB اجرا کن.')],study:['وابستگی زمان build و run را جدا بنویس؛ Dockerfile برای Go بساز و port گوش‌دادن سرویس را مشخص کن.','DATABASE_URL و PORT را از محیط بخوان؛ .env.example فقط مقدار نمونه غیرحساس داشته باشد.','تفاوت localhost داخل container با نام سرویس db را با یک درخواست اتصال توضیح بده.'],build:['در Compose سرویس api و db با volume تعریف کن؛ API به db وصل شود و migration در روش راه‌اندازی مشخص باشد.','یک Task بساز؛ containerها را stop/start یا recreate کن و ثابت کن DB از volume داده را دوباره می‌خواند؛ volume را حذف نکن.','workflow کوچک GitHub Actions برای checkout، setup Go و go test ./... بساز؛ وابستگی DB تست را اگر لازم است جدا معرفی کن.'],input:'اجرای docker compose up --build؛ ساخت Task A؛ restart سرویس‌ها؛ اجرای go test ./...',output:'سرویس پاسخ می‌دهد؛ Task A بعد از restart باقی است؛ دستور تست موفق است و README راه اجرای محیط تمیز را دارد.',question:'چرا نوشتن داده DB داخل لایه قابل حذف container کافی نیست؟',answer:'با حذف یا بازسازی container، آن لایه از بین می‌رود؛ volume برای مستقل‌کردن عمر داده از عمر container لازم است.',pitfall:'docker compose down -v داده volume را حذف می‌کند؛ برای آزمون ماندگاری، آن را روی داده واقعی اجرا نکن.'},
 {intro:['HTML ساختار و معنای محتوا را تعیین می‌کند؛ CSS اندازه و چیدمان را و JavaScript رفتار را. استفاده از button واقعی، label مرتبط با input و heading مناسب به صفحه‌کلید و فناوری‌های کمکی کمک می‌کند. ظاهر فرم بدون ارتباط label، راهنمای کافی برای همه کاربران نیست.','در این مرحله داده محلی است و هنوز درخواست API نمی‌فرستی. رویداد submit را بگیر، ورودی را بررسی کن و مدل فهرست را تغییر بده؛ سپس نمایش را از همان مدل بساز. طراحی حالت خالی و خطا باید پیش از پرشدن فهرست انجام شود، چون اولین استفاده از برنامه همین حالت است.'],reading:[read('MDN Learn Web Development','https://developer.mozilla.org/en-US/docs/Learn_web_development','HTML forms؛ CSS layout؛ JavaScript events','در بخش یادگیری وب، فرم‌های HTML و label، چیدمان Flex/Grid و مدیریت event را پیدا کن.','یک فرم Task با label، submit و پیام خطا بساز و فقط با Tab و Enter از آن استفاده کن.'),read('JavaScript.info','https://javascript.info/','Document و Introduction to events','در بخش Browser درباره انتخاب عناصر DOM و ثبت event بخوان؛ از اجرای HTML ورودی کاربر خودداری کن.','متن Task را با textContent به صفحه اضافه کن تا ورودی HTML اجرا نشود.')],study:['صفحه با header، main و فرم شامل label و input و button type=submit بساز.','برای فرم و فهرست Grid یا Flex تعریف کن؛ width ثابت بزرگ نگذار و در عرض ۳۶۰ پیکسل بررسی کن.','در submit از reload فرم جلوگیری کن؛ title را TrimSpace کن و برای خالی‌بودن پیام نزدیک input بده.'],build:['مدل []Task محلی تعریف کن و افزودن و تغییر وضعیت را روی مدل انجام بده، سپس DOM فهرست را از مدل بازسازی کن.','برای فهرست خالی پیام، برای عنوان نامعتبر خطا و برای افزودن موفق بازخورد کوتاه نمایش بده.','Task شامل متن <b>test</b> را وارد کن؛ متن باید عیناً دیده شود و HTML اجرا نشود؛ مسیر Tab و Enter را تست کن.'],input:'عنوان "Learn HTTP"؛ عنوان فقط فاصله؛ متن <b>test</b>؛ عرض مرورگر 360',output:'یک Task معتبر اضافه می‌شود؛ فاصله خطا می‌دهد؛ تگ به‌صورت متن دیده می‌شود؛ فرم و فهرست اسکرول افقی صفحه ندارند.',question:'چرا placeholder جای label را نمی‌گیرد؟',answer:'placeholder با ورود مقدار ناپدید می‌شود و همیشه نام قابل اتکای کنترل نیست؛ label نام پایدار و ارتباط قابل تشخیص برای کنترل ایجاد می‌کند.',pitfall:'استفاده از innerHTML برای متن Task می‌تواند HTML ناخواسته را اجرا کند؛ متن کاربر را به‌عنوان متن نمایش بده.'},
 {intro:['TypeScript قبل از اجرا سازگاری نوع‌ها را بررسی می‌کند؛ داده پاسخ شبکه در زمان اجرا هنوز می‌تواند خراب باشد. type و interface شکل داده را توصیف می‌کنند، اما cast کردن با as داده را اعتبارسنجی نمی‌کند. unknown یعنی پیش از استفاده باید نوع را بررسی کنی.','Union مثل "todo" | "done" حالت‌های مجاز را محدود می‌کند. Narrowing بعد از شرط، نوع را دقیق‌تر می‌کند؛ مثلاً پس از typeof value === "string" می‌توان trim را صدا زد. هدف این درس تعریف قرارداد روشن Task و خطای API و تشخیص خطای واقعی ورودی است.'],reading:[read('TypeScript Handbook','https://www.typescriptlang.org/docs/handbook/intro.html','Everyday Types، Narrowing و Object Types','نوع‌های رایج و Union را بخوان؛ در Narrowing بررسی typeof و discriminated union را دنبال کن.','پاسخ شبکه را unknown در نظر بگیر و تنها پس از بررسی فیلدهای لازم آن را Task استفاده کن.')],study:['type Task با id:number، title:string و status Union تعریف کن؛ تابع filterTasks ورودی و خروجی مشخص داشته باشد.','یک متغیر unknown شامل داده ساختگی تعریف کن؛ پیش از خواندن title، object بودن، null نبودن و string بودن title را بررسی کن.','خطا را به Union دارای code و message تبدیل کن تا فرم بداند کدام پیام را نشان بدهد.'],build:['پنل هفته ۱۳ را به فایل‌های TypeScript منتقل کن؛ anyهای اضافه را با نوع روشن یا unknown جایگزین کن.','پاسخ سالم و پاسخ title=42 را از تابع شبیه‌سازی API بگیر؛ پاسخ خراب را با پیام خطا رد کن.','نوع status نامعتبر را عمداً وارد کد کن و خطای TypeScript را ببین؛ سپس اصلاح و build کن.'],input:'{id:1,title:"Go",status:"todo"} و {id:1,title:42,status:"lost"}',output:'پاسخ اول پذیرفته؛ پاسخ دوم در بررسی runtime رد می‌شود. نسبت‌دادن status="lost" به Task باید خطای compile-time بدهد.',question:'چرا fetchResult as Task جلوی title عددی را در پاسخ واقعی نمی‌گیرد؟',answer:'as فقط ادعای نوع برای کامپایلر است و کد بررسی runtime تولید نمی‌کند؛ داده بیرونی باید واقعاً اعتبارسنجی شود.',pitfall:'optional کردن همه فیلدها برای حذف خطای TypeScript، قرارداد را ضعیف می‌کند و مشکل داده را به زمان اجرا منتقل می‌کند.'},
 {intro:['React نمایش را تابعی از state می‌داند: وقتی state عوض شود، رابط دوباره محاسبه می‌شود. Props داده‌ای است که والد به فرزند می‌دهد و فرزند باید برای تغییر آن callback والد را صدا بزند. Componentها مرز نمایش‌اند و لازم نیست هر خط JSX یک component مستقل باشد.','فهرست Task باید یک منبع حقیقت داشته باشد. تغییر مستقیم آرایه یا Task در state ممکن است باعث رفتار نامطمئن شود؛ آرایه و رکورد تازه بساز. key پایدار باعث می‌شود React هویت هر ردیف را در حذف و جابه‌جایی حفظ کند؛ index فهرست معمولاً هویت مناسبی نیست.'],reading:[read('React Learn',react,'Describing the UI؛ Adding interactivity؛ Managing state','Component و Props را بخوان، سپس State as a snapshot و Updating arrays in state را دنبال کن.','TaskList را از TaskForm جدا کن، اما state مشترک را در والد نگه دار.')],study:['مرز App، TaskForm، TaskList و TaskItem را روی کاغذ بکش؛ props و callback هرکدام را مشخص کن.','فرم کنترل‌شده با value و onChange بساز؛ مقدار input را در state نگه دار.','با map رکورد منتخب را به نسخه تازه تبدیل کن و status را عوض کن؛ برای key از ID واقعی Task استفاده کن.'],build:['سه component اصلی را بساز؛ فرم فقط title و رویداد onAdd را مدیریت کند و والد ID ایجاد کند.','تغییر وضعیت را با setTasks(prev=>prev.map(...)) پیاده کن؛ Taskهای دیگر تغییر نکنند.','چند Task اضافه، ردیف وسط را حذف و وضعیت بقیه را عوض کن؛ ورودی و state ردیف‌ها نباید جابه‌جا شوند.'],input:'سه Task با IDهای 1،2،3؛ حذف 2 و تغییر وضعیت 3',output:'فهرست شامل 1 و 3 می‌ماند؛ فقط 3 انجام‌شده است؛ عنوان و وضعیت ردیف 1 حفظ می‌شود.',question:'چرا state را مستقیماً با tasks.push تغییر نمی‌دهیم؟',answer:'state باید با مقدار تازه و setter تغییر کند تا React تغییر را دنبال کند و snapshot قبلی دست‌کاری نشود؛ از آرایه تازه مثل [...prev,newTask] استفاده می‌کنیم.',pitfall:'نگهداری یک نسخه جدا از همان فهرست در هر component، منبع حقیقت را چندتا می‌کند و داده‌ها از هم عقب می‌مانند.'},
 {intro:['درخواست شبکه ناهم‌زمان است و حالت انتظار، موفقیت و شکست دارد. fetch برای statusهایی مثل 404 الزاماً Promise را reject نمی‌کند؛ response.ok را بررسی کن و body را مطابق قرارداد بخوان. اثر یک پاسخ دیررس نباید داده جدیدتر صفحه را بی‌صدا جایگزین کند.','احراز هویت در UI تجربه کاربر را هدایت می‌کند، اما مرز امنیت سرور است. پاسخ 401 یعنی هویت معتبر نیست و می‌تواند کاربر را به ورود هدایت کند؛ 403 یعنی هویت هست ولی مجوز ندارد. داده پایدار باید پس از refresh از API خوانده شود، نه فقط از state موقتی React.'],reading:[read('React Learn',react,'Synchronizing with Effects و You Might Not Need an Effect','بخش دریافت داده و cleanup را بخوان؛ رویداد submit با effect ناشی از نمایش فرق دارد.','گرفتن فهرست را با مدیریت loading و لغو یا نادیده‌گرفتن پاسخ کهنه بساز.'),read('MDN Using Fetch','https://developer.mozilla.org/en-US/docs/Web/API/Fetch_API/Using_Fetch','Checking response status و Reading the response body','نمونه بررسی response.ok و await response.json را بخوان.','برای 200، 401 و قطع شبکه سه پیام متفاوت نمایش بده.')],study:['قرارداد login و Task API را کنار فرم بنویس؛ نوع پاسخ موفق و خطا را مشخص کن.','یک تابع request مشترک بساز که status را بررسی و خطا را به شکل قابل مصرف UI تبدیل کند.','حالت loading، خطای شبکه، 401 و فهرست خالی را جدا طراحی کن؛ عنوان Task را فقط به‌صورت متن نمایش بده.'],build:['login، logout، list و update را به API واقعی Go وصل کن؛ روش حمل هویت را با قرارداد سرور هماهنگ نگه دار.','بعد از ثبت تغییر موفق، state را از پاسخ معتبر یا خواندن مجدد API به‌روز کن؛ روی شکست شبکه موفقیت نشان نده.','صفحه را refresh کن و همان Task را از DB بخوان؛ با token حساب دوم کنترل مالکیت را از سرور امتحان کن.'],input:'GET موفق؛ token منقضی؛ خاموش‌بودن API؛ PATCH title سپس refresh',output:'موفقیت داده نشان می‌دهد؛ 401 مسیر ورود دارد؛ قطع شبکه پیام retry دارد؛ تغییر موفق پس از refresh از DB باقی می‌ماند.',question:'چرا try/catch اطراف fetch به‌تنهایی خطای HTTP 401 را نمی‌گیرد؟',answer:'fetch در پاسخ HTTP خطا هم می‌تواند Response موفق شبکه برگرداند؛ باید status یا response.ok را خودمان بررسی و به خطای برنامه تبدیل کنیم.',pitfall:'پنهان‌کردن دکمه ویرایش برای کاربر دوم، جای کنترل مالکیت در API را نمی‌گیرد.'},
 {intro:['سرویس AI هم یک وابستگی شبکه است و پیش از انتخاب مدل باید قراردادش معلوم باشد. مشخص کن چه متنی می‌گیرد، چه قالبی برمی‌گرداند، بیشینه طول چیست و چه مدت منتظر می‌ماند. این قرارداد اجازه می‌دهد Go و Python مستقل توسعه و تست شوند.','در این هفته پاسخ ثابت فقط یک stub برای تست اتصال است و نباید به‌عنوان خلاصه واقعی معرفی شود. Core API باید هنگام خاموشی سرویس AI همچنان کار کند؛ خطای وابستگی به خطای مشخص خلاصه‌سازی تبدیل می‌شود و کل پروژه را از کار نمی‌اندازد.'],reading:[read('Go net/http','https://pkg.go.dev/net/http','Client، NewRequestWithContext و Client.Timeout','روش ساخت client با timeout و request با context را بخوان؛ body پاسخ باید بسته شود.','یک درخواست به سرویس آزمایشی محلی بفرست و برای قطع اتصال خروج قابل پیش‌بینی بساز.'),read('Python HTTP server','https://docs.python.org/3/library/http.server.html','BaseHTTPRequestHandler','فقط برای شناخت درخواست و پاسخ محلی بخوان؛ http.server گزینه production نیست.','یک stub محلی با JSON ثابت بساز و صریحاً نام stub روی نتیجه بگذار.')],study:['قرارداد POST /summaries با text و پاسخ summary، model_version و error بنویس؛ ورودی و خروجی نمونه بده.','حداکثر طول تمرینی ۲۰۰۰ نویسه و timeout دو ثانیه تعیین کن و دلیل انتخاب آموزشی را ثبت کن.','جریان خطاهای empty_input، timeout، unavailable و invalid_response را رسم کن.'],build:['Python stub را روی localhost اجرا کن که همیشه summary="stub response" برمی‌گرداند؛ هیچ متن واقعی خصوصی نفرست.','Go با client دارای timeout و context آن را فراخوانی کند؛ body را بخواند، ببندد و JSON پاسخ را بررسی کند.','stub را متوقف کن؛ /health و CRUD Task باید هنوز کار کنند و فقط endpoint خلاصه خطای مشخص بدهد.'],input:'text="Shot A: character enters."؛ سرویس stub روشن، سپس خاموش؛ متن خالی',output:'در حالت روشن پاسخ صریح stub؛ حالت خاموش خطای unavailable؛ متن خالی پیش از تماس رد می‌شود؛ CRUD و health سالم‌اند.',question:'چرا قرارداد خلاصه‌ساز را پیش از انتخاب مدل می‌نویسیم؟',answer:'نیاز محصول و رفتار client باید مستقل از فناوری مدل روشن باشد؛ stub اجازه می‌دهد اتصال و شکست‌ها را بدون هزینه و ابهام مدل تست کنیم.',pitfall:'پاسخ ثابت یا rule-based را قابلیت مدل AI معرفی نکن. timeout را نامحدود نگذار.'},
 {intro:['ورودی و خروجی سرویس AI داده غیرقابل اعتمادند. محدودیت اندازه body پیش از decode جلوی خواندن بی‌حد داده را می‌گیرد؛ پس از decode هم نوع و طول text باید بررسی شود. timeout مرز زمانی است و client لغوشده باید به وابستگی downstream هم منتقل شود.','برای تست اتصال به مدل واقعی نیاز نداری. سرور آزمایشی می‌تواند پاسخ سالم، تأخیر عمدی یا JSON خراب بدهد و قرارداد Go را دقیقاً آزمایش کند. این تست‌ها رفتار شبکه و مدیریت شکست را اثبات می‌کنند؛ کیفیت مدل را نمی‌سنجند.'],reading:[read('Go net/http','https://pkg.go.dev/net/http','MaxBytesReader و NewRequestWithContext','حداکثر body و context درخواست را در مستندات بخوان؛ read محدود با validation متن متفاوت است.','body بزرگ را پیش از تماس downstream رد کن.'),read('Go httptest','https://pkg.go.dev/net/http/httptest','NewServer','یک HTTP server تستی با handler قابل تنظیم بساز.','سه handler پاسخ JSON سالم، پاسخ دیررس و متن غیرJSON را به client بده.')],study:['برای body، text خالی، text بلند و نوع نادرست جدول محدودیت و کد خطا بنویس.','client و context را طوری طراحی کن که timeout سرور آزمایشی طول تست را چند ثانیه طولانی نکند.','پاسخ مدل را decode و فیلد summary را بررسی کن؛ پاسخ HTML یا JSON ناقص را خروجی موفق ندان.'],build:['سه تست با httptest.NewServer بنویس: JSON معتبر، تأخیر بیش از timeout و پاسخ {broken.','در هر تست علاوه بر خطا، زمان اتمام محدود و نبود panic را بررسی کن؛ sleep طولانی غیرضروری نگذار.','یک درخواست body بزرگ بفرست و با شمارنده stub ثابت کن downstream اصلاً فراخوانی نشده است.'],input:'{"summary":"ok"}؛ تأخیر 200ms با timeout=50ms؛ پاسخ {broken؛ body بالاتر از سقف',output:'سالم summary=ok؛ تأخیر خطای timeout؛ JSON خراب invalid_response؛ body بزرگ 413 یا خطای قراردادی و بدون تماس downstream.',question:'چرا تست پاسخ خراب را با مدل واقعی اجرا نمی‌کنیم؟',answer:'هدف رفتار client در شکست قطعی است؛ سرور تستی پاسخ دقیق و تکرارپذیر می‌دهد، درحالی‌که مدل یا شبکه واقعی نوسان و هزینه اضافه می‌آورند.',pitfall:'retry کور روی همه خطاها می‌تواند بار را چندبرابر کند؛ ورودی نامعتبر و JSON خراب نباید بی‌نهایت retry شوند.'},
 {intro:['پاسخ مدل بدون نسخه قابل بازتولید نیست: تغییر checkpoint یا tokenizer می‌تواند خروجی یک ورودی ثابت را عوض کند. نسخه مدل، تنظیمات اجرا و شناسه درخواست را از متن خروجی جدا نگه دار تا client بتواند نتیجه و منشأ آن را گزارش کند.','پیکربندی باید هنگام شروع اعتبارسنجی شود. نبود فایل checkpoint را نباید تا اولین درخواست پنهان کرد یا بی‌صدا مدل دیگری جایگزین کرد. اگر fallback به مدل پایه داری، نسخه استفاده‌شده را صریح در پاسخ ثبت کن؛ secret و مسیر حساس محلی برای client لازم نیست.'],reading:[read('Hugging Face Fine-tuning','https://huggingface.co/docs/transformers/main/training','Saving و loading و checkpoint در راهنمای آموزش','بخش‌های مرتبط با ذخیره و استفاده مجدد مدل را همراه نسخه نصب‌شده بخوان.','یک model_version ثابت و مسیر checkpoint قابل تنظیم به سرویس اضافه کن.'),read('Go os package','https://pkg.go.dev/os','LookupEnv و Stat','تفاوت نبود متغیر محیطی با مقدار خالی و بررسی وجود فایل را بخوان.','برای CHECKPOINT_PATH گم‌شده خطای روشن شروع سرویس تولید کن.')],study:['schema پاسخ را با result.summary و metadata.model_version و metadata.request_id بنویس.','پیکربندی MODEL_ID، CHECKPOINT_PATH و TIMEOUT را تعریف و اعتبارسنجی زمان شروع را مشخص کن.','سیاست fallback را روی کاغذ بنویس؛ مشخص کن چه خطایی fallback می‌گیرد و چطور client از آن باخبر می‌شود.'],build:['تنظیمات را از محیط بخوان و در شروع، مقدارهای اجباری و وجود فایل مدل را بررسی کن.','پاسخ هر درخواست نسخه واقعی انتخاب‌شده را حمل کند؛ مسیر فایل داخلی یا secret را در پاسخ چاپ نکن.','با مسیر ناموجود و config ناقص اجرا کن؛ سپس مسیر معتبر بده و یک درخواست ثابت را با همان نسخه تکرار کن.'],input:'MODEL_ID=baseline-v1؛ CHECKPOINT_PATH ناموجود؛ سپس checkpoint معتبر tuned-v1',output:'پیکربندی خراب خطای startup یا readiness روشن دارد؛ پاسخ سالم metadata درست baseline-v1 یا tuned-v1 را نشان می‌دهد و تعویض پنهان رخ نمی‌دهد.',question:'چرا model_version باید با نتیجه برگردد و صرفاً در README نباشد؟',answer:'README ممکن است نسخه فعلی کد را توصیف کند ولی درخواست از checkpoint دیگری پاسخ گرفته باشد؛ metadata خود پاسخ منشأ همان نتیجه را ثبت می‌کند.',pitfall:'نام فایل checkpoint به‌تنهایی شناسه مطمئن نسخه نیست؛ نام نسخه یا hash ثابت و تنظیمات قابل ثبت انتخاب کن.'},
 {intro:['ارزیابی API مدل دو بخش جدا دارد: آیا سرویس قرارداد HTTP را درست اجرا می‌کند و آیا خلاصه، محتوای متن را درست حفظ می‌کند؟ latency فقط کیفیت فنی زمان پاسخ را می‌سنجد و به‌تنهایی نشانه خوب‌بودن مدل نیست.','برای مقایسه، ورودی‌ها، نسخه مدل و تنظیمات باید ثابت بمانند. متن خالی، کوتاه، بلند، فارسی و شامل نام ویژه سناریوهای متفاوت‌اند. خطای سرویس را با نمره ضعیف خلاصه قاطی نکن؛ یک درخواست شکست‌خورده اصلاً خلاصه قابل ارزیابی تولید نکرده است.'],reading:[read('Go time package','https://pkg.go.dev/time','Now و Since','اندازه‌گیری زمان سپری‌شده را بخوان؛ timestamp تقویمی را از duration جدا کن.','مدت هر درخواست را با time.Since ثبت کن و واحد میلی‌ثانیه را کنار عدد بنویس.'),read('Hugging Face training guide','https://huggingface.co/docs/transformers/main/training','Evaluation در راهنمای Fine-tuning','تفاوت ارزیابی داده ثابت و آموزش را مرور کن؛ سنجه باید با مسئله هماهنگ باشد.','در گزارش فنی، موفقیت HTTP و کیفیت محتوایی را دو ستون جدا بگذار.')],study:['فرم گزارش شامل ورودی، model_version، status، latency_ms، خروجی و خطای محتوا بساز.','پنج ورودی از پیش ثابت بنویس: خالی، یک جمله، دو پاراگراف، فارسی با نام شخص ساختگی و متن نزدیک سقف.','برای حفظ نام‌ها و رخدادهای اصلی معیار ساده تعریف کن و مثال ادعای اضافه مدل را مشخص کن.'],build:['پنج ورودی را با نسخه ثابت سه بار اجرا کن؛ زمان هر تکرار و میانه را ثبت کن.','متن نامعتبر را در گزارش فنی به‌عنوان رد درست ورودی ثبت کن؛ آن را نمره صفر کیفیت خلاصه نده.','README گزارش را با فرمان، نسخه مدل، سخت‌افزار واقعی و محدودیت نمونه کوچک بنویس.'],input:'["", "A enters.", دو پاراگراف ساختگی، متن فارسی با نام سارا، متن نزدیک سقف]',output:'برای هر نمونه status و latency و نسخه مشخص؛ متن خالی رد می‌شود؛ خروجی‌ها از نظر حفظ نام و رخداد جدا بررسی می‌شوند؛ نتیجه ساختگی گزارش نمی‌شود.',question:'آیا کوتاه‌ترشدن latency ثابت می‌کند مدل خلاصه بهتری می‌دهد؟',answer:'خیر؛ زمان پاسخ و کیفیت محتوا دو سنجه مستقل‌اند. یک پاسخ سریع می‌تواند محتوای نادرست یا ناقص داشته باشد.',pitfall:'مقایسه CPU و GPU یا دو مدل روی ورودی، batch و تنظیمات متفاوت نتیجه منصفانه و قابل تکرار نمی‌دهد.'},
 {intro:['StudioFlow یک پروژه آموزشی مدیریت تولید انیمیشن است. Project مالک اعضا و Sequenceهاست؛ Sequence مجموعه Shotها را گروه می‌کند؛ Task کار قابل واگذاری روی Shot است. User هویت فرد و Membership رابطه او با یک پروژه و نقش را مشخص می‌کند؛ نقش معمولاً متعلق به عضویت در پروژه است، نه اختیار سراسری نامحدود.','در دیتابیس باید ارتباط‌ها و مرز دسترسی روشن باشند: Shot نباید به Sequence پروژه دیگر وصل شود. Go/Gin قواعد و مجوز را اعمال می‌کند؛ PostgreSQL داده اصلی است؛ Redis فقط داده قابل بازسازی را cache می‌کند و Python خلاصه‌سازی محدودی ارائه می‌دهد. اینها قابلیت پروژه تمرینی‌اند و با سایت یادگیری DevPath یکی نیستند.'],reading:[read('PostgreSQL Tutorial',pg,'Tables، Foreign Keys و Transactions','schema چندجدولی و محدودیت رابطه را مرور کن؛ Foreign Key به‌تنهایی عضویت در همان پروژه را تضمین نمی‌کند.','برای Project، Membership، Sequence و Shot کلید و قواعد مالکیت بنویس.'),read('Go RESTful API Tutorial',gin,'Routing، JSON input و response handlers','ساخت endpoint را مرور کن، سپس قواعد مجوز را از آموزش نمونه فراتر خودت اضافه کن.','جدول CRUD پروژه، Sequence و Shot را با role لازم کنار هر endpoint بنویس.')],study:['ERD برای project، membership، sequence، shot و task رسم کن و cardinality هر رابطه را بنویس.','ماتریس نقش مدیر و عضو را برای ساخت پروژه، افزودن عضو، تغییر Shot و خواندن داده تهیه کن.','مرز API عمومی محصول و سرویس AI داخلی را رسم کن؛ شکست AI نباید CRUD تولید را متوقف کند.'],build:['migrationهای هسته را بساز؛ عضویت کاربر و project_id را در تمام عملیات داده بررسی کن.','CRUD پروژه، Sequence و Shot را بساز و سناریوی مدیرA، عضوA و غریبهB را روی آنها اجرا کن.','تلاش اتصال Shot پروژه A به Sequence پروژه B را رد کن؛ تغییر نباید نیمه‌تمام در DB ذخیره شود.'],input:'Project A با مدیر و عضو؛ Project B با غریبه؛ ساخت Shot A با sequence_id متعلق به B',output:'رابطه نامعتبر رد و DB دست‌نخورده است؛ غریبه نمی‌تواند پروژه A را بخواند یا تغییر دهد؛ نقش‌ها طبق ماتریس اعمال می‌شوند.',question:'چرا role=admin سراسری برای تمام پروژه‌ها می‌تواند اشتباه باشد؟',answer:'فرد ممکن است فقط مدیر یک پروژه باشد؛ نگهداری نقش روی membership اجازه می‌دهد مجوزها بر اساس همان پروژه و همان عمل بررسی شوند.',pitfall:'وجود project_id در body دلیل دسترسی کاربر نیست؛ سرور باید عضویت و تعلق داده را خودش بررسی کند.'},
 {intro:['گردش کار تولید از وضعیت‌های تعریف‌شده و قواعد تغییر آنها ساخته می‌شود. Shot می‌تواند todo، in_progress، review و approved داشته باشد؛ تعریف وضعیت بدون مشخص‌کردن فرد مجاز و transitionها کافی نیست. Task assignment به فرد عضو همان پروژه تعلق می‌گیرد.','نسخه فایل رکورد تاریخچه است؛ آپلود یا ثبت v2 نباید v1 را بازنویسی کند. Deadline یک زمان یا تاریخ قراردادی با منطقه زمانی روشن است. داشبورد باید تعدادها را از داده واقعی همان پروژه حساب کند؛ داده نمایشی و محاسبه client جای کنترل و شمارش درست سمت سرور را نمی‌گیرد.'],reading:[read('React Learn',react,'Managing state و Sharing state between components','مدل state فرم و نمایش داده‌های مرتبط را مرور کن؛ وضعیت مشتق‌شده را بی‌دلیل دو بار ذخیره نکن.','شمارش Shotهای هر وضعیت را از فهرست معتبر بساز و بعد از تغییر موفق API به‌روز کن.'),read('PostgreSQL Tutorial',pg,'Transactions و Foreign Keys','ثبت نسخه و نسبت‌دادن Task به عضو را با قواعد DB و transaction مرور کن.','برای نسخه‌ها کلید یکتای مناسب مثل (shot_id,version) تعریف کن.')],study:['جدول transition وضعیت Shot و role مجاز بنویس؛ درباره برگشت approved به review تصمیم روشن بگیر.','schema file_versions را با shot_id، version، storage_reference و زمان ثبت طراحی کن؛ مسیر ذخیره عمومی فایل را از secret جدا نگه دار.','قرارداد Deadline و نمایش زمان تهران را مشخص کن؛ در DB زمان استاندارد ذخیره و در UI تبدیل کن.'],build:['فرم‌های Project، Sequence، Shot، Task و اعضا را به API وصل و حالت loading/error/empty را پیاده کن.','دو نسخه فایل یک Shot ثبت و سپس v1 را دوباره بخوان؛ نسخه قبلی نباید تغییر کرده باشد.','Shot را از in_progress به review ببر و شمارش داشبورد را مقایسه کن؛ عضو غریبه نباید با درخواست دستی transition اجرا کند.'],input:'Shot 7 با v1؛ ثبت v2؛ تغییر status به review؛ واگذاری Task به کاربر بیرون پروژه',output:'v1 و v2 مستقل قابل مشاهده‌اند؛ شمارش review یک واحد زیاد می‌شود؛ assignment فرد غیرعضو رد می‌شود؛ خطای شبکه موفقیت جعلی نشان نمی‌دهد.',question:'چرا تعداد done را جدا در state نگه نداریم وقتی از فهرست Task قابل محاسبه است؟',answer:'دو نسخه از یک حقیقت ممکن است از هم عقب بمانند؛ شمارش مشتق‌شده از داده معتبر یا پاسخ server، با تغییر فهرست هماهنگ می‌ماند.',pitfall:'آپلود فایل و امنیت مسیر ذخیره موضوع جداگانه است؛ برای نسخه آموزشی می‌توان metadata فایل ساختگی را ثبت کرد ولی آن را آپلود واقعی معرفی نکن.'},
 {intro:['Deploy یعنی اجرای قابل تکرار سرویس در محیطی که با لپ‌تاپ توسعه فرق دارد. تنظیمات، شبکه، storage، migration و healthcheck باید مشخص باشند. log برای تشخیص خطاست و نباید رمز، token یا متن خصوصی Shot را منتشر کند.','استقرار سالم فقط بازشدن صفحه نیست؛ داده باید پس از restart باقی بماند، مجوزها درست کار کنند و شکست سرویس AI محصول را کامل قطع نکند. backup و rollback باید قبل از آزمایش تغییر DB روشن باشند؛ برگشت image قدیمی الزاماً migration ناسازگار را برنمی‌گرداند.'],reading:[read('Docker Get Started',docker,'Compose، volumes و environment variables','چندسرویسی‌بودن، شبکه داخلی و نگهداری داده را مرور کن؛ تفاوت فایل env نمونه و واقعی را مشخص کن.','Compose پروژه نهایی را روی clone تازه و داده آزمایشی اجرا کن.'),read('PostgreSQL documentation',pg,'Transactions و مراحل ساخت database','اجرای schema و transaction را برای migration مرور کن.','روش راه‌اندازی DB تازه و روش backup پیش از تغییر را در README تفکیک کن.')],study:['جدول سرویس‌ها و portهای لازم را بنویس؛ DB و Redis فقط در شبکه موردنیاز در دسترس باشند.','برای هر سرویس health/readiness و timeout ارتباط وابسته را مشخص کن؛ log را با request_id و بدون داده حساس طراحی کن.','برنامه backup و rollback آزمایشی را با نسخه image و سازگاری schema بنویس.'],build:['Go، PostgreSQL، Redis و سرویس Python را در Compose اجرا کن؛ migration و env نمونه را مستند کن.','تست نقش‌ها، تعلق Shot/Sequence و قطع AI را اجرا؛ غریبهB و داده خصوصیA را در تست واقعی API بررسی کن.','از clone تازه در محیط آزمایشی یا میزبان انتخابی اجرا کن؛ آدرس و وضعیت واقعی deploy را ثبت و پس از restart داده را بررسی کن.'],input:'دو کاربر و دو پروژه؛ restart DB؛ قطع Python؛ درخواست غیرمجاز؛ migration روی DB آزمایشی',output:'داده پس از restart باقی است؛ AI unavailable پیام روشن دارد؛ CRUD اصلی کار می‌کند؛ غریبه داده پروژه را نمی‌گیرد؛ روش rollback محدودیت‌های schema را بیان می‌کند.',question:'چرا برگشت به image قبلی همیشه برای rollback کافی نیست؟',answer:'ممکن است migration schema را به شکلی تغییر داده باشد که نسخه کد قبلی با آن سازگار نباشد؛ rollback باید سازگاری کد، DB و backup را با هم در نظر بگیرد.',pitfall:'نسخه نمایشی دارای داده ساختگی را با داده واقعی تولید اجرا نکن و secret را در image یا Git bake نکن.'},
 {intro:['README قرارداد شروع کار با پروژه برای کسی است که گفت‌وگوی ما را ندیده است. باید مسئله، دامنه، نصب، تنظیم محیط، migration، تست، نمونه درخواست و محدودیت‌های واقعی را توضیح دهد. دستور اجرا را با محیط تمیز امتحان کن؛ توضیحی که فقط روی دستگاه خودت جواب می‌دهد قابل اتکا نیست.','رزومه مجموعه ادعاهای قابل دفاع است. عنوان Junior Backend Developer و مهارت‌های Go، PostgreSQL، REST و Docker باید به نمونه کد، تست یا تصمیم فنی قابل نشان‌دادن وصل شوند. تصویر و ویدئو نتیجه را نشان می‌دهند، اما جای سورس و امکان اجرا را نمی‌گیرند.'],reading:[read('GitHub documentation','https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/about-readmes','What a README contains و Discoverability','راهنمای README را بخوان و بخش‌های لازم پروژه خودت را انتخاب کن؛ متن تبلیغاتی آماده را کپی نکن.','README انگلیسی با Quick start، Tests، API، Architecture و Limitations بنویس.'),read('Docker Get Started',docker,'Run the application با Compose','دستور اجرای پروژه را با نیاز واقعی env و DB بازبینی کن.','README را در یک پوشه clone تازه دنبال کن و هر مرحله گمشده را اصلاح کن.')],study:['جدول ادعا و شاهد بساز: مثلاً Authorization ← تست دسترسی دو کاربر و فایل handler مربوط.','ساختار README انگلیسی را با مسئله محصول و دامنه نسخه اول شروع کن؛ سپس نصب و تست و محدودیت را بنویس.','سه تصمیم فنی مثل PostgreSQL، مرز سرویس AI و cache را با دلیل و هزینه‌شان توضیح بده.'],build:['مخزن را برای فایل env واقعی، token، checkpoint حجیم و داده شخصی بررسی کن؛ فقط نمونه غیرحساس نگه دار.','Quick start را از clone تازه اجرا، تست‌ها را بگیر و یک screenshot و ویدئوی کوتاه گردش کار ثبت کن.','لینک دمو واقعی را جدا از لینک سورس بنویس؛ اگر چیزی deploy نشده صریحاً وضعیتش را ذکر کن.'],input:'فرد تازه با Node/Go/Docker موردنیاز؛ clone پروژه؛ فقط دستورهای README',output:'فرد می‌تواند env نمونه را پر، schema را بسازد، سرویس را اجرا و تست کند؛ هر مهارت رزومه به شاهد عملی وصل است؛ لینک دمو واقعاً باز می‌شود.',question:'چه چیزی در README یک دستور نصب را قابل اعتماد می‌کند؟',answer:'پیش‌نیازها و نسخه‌ها روشن‌اند، مقدارهای نمونه وجود دارند و همان دستورها از محیط تمیز اجرا شده‌اند؛ محدودیت و مرحله دستی پنهان نمانده است.',pitfall:'عبارت Experienced in را از نمونه رزومه فقط وقتی استفاده کن که تجربه واقعی قابل نشان‌دادن داری؛ کپی ادعای آماده ارزش پروژه را کم می‌کند.'},
 {intro:['ممیزی به معنی اضافه‌کردن ابزار تازه نیست؛ فاصله رفتار فعلی با معیار تحویل را پیدا می‌کنی. هر نقص باید trigger، رفتار فعلی، رفتار مورد انتظار و اهمیت داشته باشد. مشکل کنترل مالکیت معمولاً از تغییر رنگ یک فرم اولویت بیشتری دارد.','برای اصلاح، ابتدا تستی بنویس که روی نقص شکست بخورد. بعد کمترین تغییر مسئول را انجام بده و تست‌های مرتبط را اجرا کن. بستن issue بدون مشاهده تست و سناریوی نهایی، فقط تغییر برچسب است و شاهد رفع اشکال نیست.'],reading:[read('Go Add a test',testing,'Test failure و test execution','قالب تست و پیام شکست را مرور کن؛ ورودی باگ را در fixture پایدار نگه دار.','برای هرکدام از سه نقص منتخب یک تست regression بساز.'),read('Go database access','https://go.dev/doc/database/querying','Handling errors و scanning query results','مسیر نبود داده و خطای DB را مرور کن.','در ممیزی فرق not found، unauthorized و DB unavailable را با سناریو مشخص بررسی کن.')],study:['چک‌لیست Backend را با endpointهای واقعی تطبیق بده؛ سه نقص مهم را با ورودی بازتولیدپذیر ثبت کن.','برای هر نقص بنویس کدام لایه مسئول است و چه داده‌ای نباید تغییر کند؛ رفتار انتظار را پیش از اصلاح مشخص کن.','تست بازتولید را اجرا و شکست واقعی را ثبت کن؛ تستی که قبل از اصلاح سبز است هنوز نقص را نشان نداده است.'],build:['سه نقص منتخب را یکی‌یکی با تست نگهبان اصلاح کن؛ کد نامرتبط را در همین تغییر refactor نکن.','تست کامل دو کاربر و CRUD و Compose را پس از اصلاح اجرا کن؛ داده آزمایشی هر تست مستقل باشد.','در گزارش، علت ریشه‌ای، تغییر مسئول و فرمان تست موفق را کنار issue بنویس.'],input:'سه issue شامل دسترسی به Task دیگران، عنوان خالی و نبود env؛ هرکدام با درخواست یا فرمان دقیق',output:'سه تست پیش از fix شکست و پس از fix موفق می‌شوند؛ سناریوی مجوز و اجرای تمیز هم موفق است؛ issueها شواهد روشن دارند.',question:'چرا تستی که قبل از اصلاح سبز است، برای اثبات رفع همان باگ کافی نیست؟',answer:'ممکن است اصلاً مسیر خطا را اجرا نکرده یا انتظار لازم را نسنجد؛ باید رفتار خراب را پیش از fix آشکار کند تا تغییر نتیجه شاهد اصلاح باشد.',pitfall:'هفته رفع نقص را به بازنویسی کامل معماری تبدیل نکن؛ فقط تغییر لازم با شاهد روشن انجام بده.'},
 {intro:['ارزیابی پایانی باید توان مستقل را از توان همراه راهنما جدا کند. یک مسئله کوچک با ورودی، خروجی، مالکیت و خطا تعریف کن و بدون کپی endpoint بساز. استفاده از مستندات برای جزئیات مجاز است، اما ابتدا طرح را خودت بنویس و مشخص کن کجا کمک گرفتی.','مصاحبه تمرینی حفظ تعریف‌ها نیست. برای Interface، Goroutine، Transaction، JWT و Docker یک نمونه واقعی از پروژه توضیح بده: مسئله چه بود، چه انتخاب کردی، چه شکست می‌خورد و چطور تست کردی. پاسخ ناقص را با برنامه مرور مشخص ادامه بده؛ تمام‌شدن هفته تضمین استخدام نیست.'],reading:[read('Go Tutorials','https://go.dev/doc/tutorial/','Tutorials مرتبط با module، test و API','در دور اول بدون بازکردن پاسخ کار کن؛ پس از تلاش، بخش دقیق مرتبط با شکافت را مرور کن.','دو سؤال مبهم را به یک تمرین ۳۰ دقیقه‌ای با خروجی قابل بررسی تبدیل کن.'),read('PostgreSQL Tutorial',pg,'Joins و Transactions','پس از پاسخ مستقل، مثال خودت را با مفهوم رسمی تطبیق بده.','شرح بده چرا دو write مربوط به یک عملیات باید در transaction باشند.')],study:['مسئله PATCH /tasks/:id را با مالکیت، title و status و پاسخ خطا روی کاغذ طراحی کن.','یک پیاده‌سازی کوچک query پارامتری با owner_id بساز؛ برای خراب‌بودن ورودی، نبود Task و کاربر دیگر تست بنویس.','یک باگ عمدی مثل حذف شرط مالکیت را با تست پیدا کن و دلیل شکست را توضیح بده.'],build:['برای هرکدام از Interface، error، Goroutine/Channel، Transaction، JWT و Docker یک سؤال و مثال پروژه ضبط یا یادداشت کن.','به شش سؤال در ۲۰ دقیقه پاسخ بده و برای هر پاسخ شاهد فایل یا تست مرتبط را ثبت کن.','دو ضعف واقعی را انتخاب و برنامه مرور شامل منبع، تمرین و معیار فهم بنویس؛ سطح مهارت را با شاهد به‌روز کن.'],input:'Task A؛ درخواست PATCH از B؛ title سفید؛ پرسش «JWT معتبر چرا مجوز همه رکوردها نیست؟»',output:'B هیچ تغییری ایجاد نمی‌کند؛ title سفید رد می‌شود؛ پاسخ تفاوت هویت و مالکیت را با تست واقعی توضیح می‌دهد؛ ضعف‌ها برنامه مرور دارند.',question:'برای اثبات توان مستقل در Backend چه چیزی فراتر از تیک درس نشان می‌دهی؟',answer:'کد قابل اجرا، تست ورودی سالم و خراب، کنترل مالکیت، توضیح تصمیم و نمونه debug بدون کپی؛ هر ادعا به خروجی واقعی وصل است.',pitfall:'روایت رزومه نباید از شواهد جلوتر باشد؛ موضوعی را که فقط با راهنما انجام می‌دهی به‌عنوان تسلط مستقل ثبت نکن.'}
];
export const backendLessons:Record<string,LessonGuide>={};
weeks.forEach((week,index)=>{
 const t=topics[index];
 for(const a of week.activities.filter(a=>a.track==='backend')){
  const practice=a.id.endsWith('-practice');
  backendLessons[a.id]={intro:t.intro,steps:(practice?t.build:t.study).map((body,i)=>({title:(practice?'گام ساخت ':'گام یادگیری ')+(i+1),body})),resourceSections:t.reading,exercise:{task:practice?a.description:t.question,input:t.input,expected:practice?t.output:t.answer,hint:practice?t.pitfall+' برای محدودکردن مشکل، فقط سناریوی '+t.input+' را با انتظار نوشته‌شده مقایسه کن.':t.study[1]+' سپس دلیل رفتار را پیش از دیدن خروجی بنویس.'},checks:[a.acceptance,practice?t.output:t.answer],pitfalls:[t.pitfall],...(t.code?{example:{language:index<12?'go':'text',code:t.code,explanation:t.explanation!}}:{})};
 }
});
